-- Synthetic data of a fictitious card shop for the Lesson 13 lab. Every person is fake:
-- the surnames say so, the e-mails use the reserved domain example.com and the CPFs start with 000.
-- Every date is Unix time in seconds (UTC).

CREATE SCHEMA shop;
CREATE TABLE shop.stores (store_id text PRIMARY KEY, city text NOT NULL, uf text NOT NULL);
CREATE TABLE shop.customers (customer_id integer PRIMARY KEY, store_id text NOT NULL REFERENCES shop.stores, full_name text NOT NULL, email text NOT NULL, cpf text NOT NULL, phone text, birth_unix bigint, city text, accessibility_need text, marketing_consent boolean NOT NULL, consent_unix bigint, created_unix bigint NOT NULL);
CREATE TABLE shop.orders (order_id integer PRIMARY KEY, customer_id integer NOT NULL REFERENCES shop.customers, store_id text NOT NULL REFERENCES shop.stores, ordered_unix bigint NOT NULL, product text NOT NULL, set_name text NOT NULL, quantity integer NOT NULL, unit_price numeric(10,2) NOT NULL, payment_method text NOT NULL, card_last4 text);

